styles:
.evo-aff{
    --aubergine:#230F33; --aubergine-deep:#1a0b26; --mauve:#715588; --mauve-soft:#8f74a6;
    --ink:#241033; --muted:#6f6779; --hair:#ece7f1; --hair-strong:#ddd4e6;
    --bg:#ffffff; --card:#ffffff; --chip:#f4f1f7;
    --sans:"Outfit","Segoe UI",system-ui,-apple-system,"Helvetica Neue",Arial,sans-serif;
    --r:16px;
    font-family:var(--sans);color:var(--ink);background:var(--bg);
    -webkit-font-smoothing:antialiased;line-height:1.55;
    padding:clamp(20px,5vw,60px) 20px 72px;
  }
  .evo-aff *{box-sizing:border-box}
  .evo-aff .wrap{max-width:880px;margin:0 auto}
  .evo-aff .eyebrow{font-size:12px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--mauve);margin:0 0 12px}
  .evo-aff .hero-h{font-size:clamp(30px,5.4vw,46px);line-height:1.06;letter-spacing:-.02em;font-weight:700;margin:0 0 14px;text-wrap:balance;color:var(--aubergine)}
  .evo-aff .lede{font-size:clamp(15px,2.2vw,18px);color:var(--muted);max-width:60ch;margin:0 0 24px}
  .evo-aff .cta-row{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:0 0 26px}
  .evo-aff .btn{display:inline-block;font-family:inherit;font-size:16px;font-weight:600;text-decoration:none;border-radius:12px;padding:14px 26px;transition:background .15s,border-color .15s,transform .1s;cursor:pointer}
  .evo-aff .btn:active{transform:translateY(1px)}
  .evo-aff .btn.primary{color:#fff;background:var(--mauve);border:1.5px solid var(--mauve)}
  .evo-aff .btn.primary:hover{background:#836399;border-color:#836399;color:#fff}
  .evo-aff .btn.ghost{color:var(--aubergine);background:#fff;border:1.5px solid var(--hair-strong)}
  .evo-aff .btn.ghost:hover{border-color:var(--mauve-soft);background:#fbfafc;color:var(--aubergine)}
  .evo-aff .btn:focus-visible{outline:none;box-shadow:0 0 0 4px rgba(143,116,166,.35)}
  .evo-aff .stats{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 8px}
  .evo-aff .stat{flex:1 1 150px;background:var(--card);border:1px solid var(--hair);border-radius:12px;padding:14px 16px}
  .evo-aff .stat b{display:block;font-size:22px;font-weight:700;letter-spacing:-.01em;font-variant-numeric:tabular-nums;color:var(--aubergine)}
  .evo-aff .stat span{font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}
  .evo-aff section{margin-top:clamp(36px,6vw,56px)}
  .evo-aff h2{font-size:clamp(22px,3.4vw,30px);line-height:1.15;letter-spacing:-.015em;font-weight:700;color:var(--aubergine);margin:0 0 8px;text-wrap:balance}
  .evo-aff .sec-sub{font-size:15px;color:var(--muted);max-width:64ch;margin:0 0 22px}
  .evo-aff .steps{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
  .evo-aff .step{background:var(--card);border:1px solid var(--hair);border-radius:var(--r);padding:20px}
  .evo-aff .step .n{display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:999px;background:var(--chip);color:var(--mauve);font-weight:700;font-size:15px;margin-bottom:12px}
  .evo-aff .step h3{font-size:17px;font-weight:700;margin:0 0 6px;color:var(--ink)}
  .evo-aff .step p{font-size:14px;color:var(--muted);margin:0}
  .evo-aff .panel{background:linear-gradient(160deg,#2a1240,var(--aubergine) 60%,var(--aubergine-deep));border-radius:var(--r);padding:clamp(24px,4.5vw,40px);color:#fff;box-shadow:0 24px 60px -34px rgba(26,4,26,.7)}
  .evo-aff .panel h2{color:#fff}
  .evo-aff .panel .sec-sub{color:#cdbcde}
  .evo-aff .math{display:flex;flex-wrap:wrap;gap:12px;margin:18px 0 6px}
  .evo-aff .math .m{flex:1 1 160px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);border-radius:12px;padding:16px}
  .evo-aff .math .m b{display:block;font-size:26px;font-weight:700;font-variant-numeric:tabular-nums;letter-spacing:-.01em}
  .evo-aff .math .m span{font-size:12px;text-transform:uppercase;letter-spacing:.07em;color:#cdbcde}
  .evo-aff .panel .fine{font-size:12px;color:#b9a8ca;margin:14px 0 0}
  .evo-aff .panel .btn.primary{margin-top:18px}
  .evo-aff .cards{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}
  .evo-aff .card{background:var(--card);border:1px solid var(--hair);border-radius:var(--r);padding:20px}
  .evo-aff .card h3{font-size:16px;font-weight:700;margin:0 0 6px;color:var(--ink)}
  .evo-aff .card p{font-size:14px;color:var(--muted);margin:0}
  .evo-aff .card a{color:var(--aubergine);font-weight:600;text-decoration:none}
  .evo-aff .card a:hover{text-decoration:underline}
  .evo-aff .cmp{overflow-x:auto;-webkit-overflow-scrolling:touch;border:1px solid var(--hair);border-radius:var(--r);background:var(--card)}
  .evo-aff .cmp table{width:100%;border-collapse:collapse;min-width:560px;font-size:14px}
  .evo-aff .cmp th{text-align:left;font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);padding:14px 16px;border-bottom:1px solid var(--hair-strong);background:var(--chip);white-space:nowrap}
  .evo-aff .cmp th.evo{color:var(--aubergine)}
  .evo-aff .cmp td{padding:13px 16px;border-bottom:1px solid var(--hair);color:var(--muted);vertical-align:top}
  .evo-aff .cmp tr:last-child td{border-bottom:none}
  .evo-aff .cmp td:first-child{font-weight:600;color:var(--ink)}
  .evo-aff .cmp td.evo{color:var(--ink)}
  .evo-aff .cmp-note{font-size:13px;color:var(--muted);font-style:italic;margin:12px 0 0}
  .evo-aff .cmp-hint{display:none;font-size:12px;color:var(--muted);margin:0 0 8px}
  @media(max-width:760px){.evo-aff .cmp-hint{display:block}}
  .evo-aff .who{background:var(--card);border:1px solid var(--hair);border-radius:var(--r);padding:22px 24px}
  .evo-aff .who ul{margin:10px 0 0;padding:0;list-style:none;display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
  .evo-aff .who li{font-size:14px;color:var(--ink);background:var(--chip);border-radius:10px;padding:11px 14px}
  .evo-aff .who .note{font-size:13px;color:var(--muted);margin:14px 0 0}
  .evo-aff .faq details{background:var(--card);border:1px solid var(--hair);border-radius:12px;margin-bottom:10px;overflow:hidden}
  .evo-aff .faq summary{cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:15px;font-weight:600;color:var(--ink);padding:16px 18px}
  .evo-aff .faq summary::-webkit-details-marker{display:none}
  .evo-aff .faq summary:after{content:"+";font-size:20px;font-weight:400;color:var(--mauve);flex:none;line-height:1}
  .evo-aff .faq details[open] summary:after{content:"\2212"}
  .evo-aff .faq summary:focus-visible{outline:none;box-shadow:inset 0 0 0 3px rgba(143,116,166,.35);border-radius:12px}
  .evo-aff .faq .a{padding:0 18px 16px;font-size:14px;color:var(--muted)}
  .evo-aff .faq .a a{color:var(--aubergine);font-weight:600;text-decoration:none}
  .evo-aff .faq .a a:hover{text-decoration:underline}
  .evo-aff .foot{margin-top:30px;font-size:12px;color:var(--muted);text-align:center;max-width:72ch;margin-left:auto;margin-right:auto}
  @media(max-width:760px){
    .evo-aff .steps{grid-template-columns:1fr}
    .evo-aff .cards{grid-template-columns:1fr}
    .evo-aff .who ul{grid-template-columns:1fr}
  }
